import { z } from "zod";
import { canonicalUrl, SITE_ORIGIN } from "@/lib/seo";
import type { Extension } from "@/lib/extensions";

/**
 * Extension landing-page copy — lamill-owned.
 *
 * `extensions.json` (Tabmill) owns the facts: name, store URL, permissions,
 * status. The page copy lives here, one file per extension in
 * `src/content/extension-pages/<slug>.ts`, joined by slug, so a Tabmill export
 * never overwrites it. An extension without a copy file renders the short page.
 *
 * Media sizes come from `src/content/extension-media.json`, generated by
 * `scripts/ext-media.sh`. A media item whose file isn't in the manifest yet is
 * dropped from the page (with a build warning) rather than rendered without
 * width/height.
 */

const faqSchema = z.object({ q: z.string(), a: z.string() });

export const extensionPageSchema = z.object({
  slug: z.string().regex(/^[a-z0-9-]+$/, "slug must be kebab-case"),
  /** <title>. */
  title: z.string(),
  h1: z.string(),
  /** Meta description, ≤ ~155 chars. */
  description: z.string().max(160),
  /** One line under the H1. */
  valueProp: z.string(),
  /** Short facts row under the hero, e.g. ["Free", "v0.1.0"]. */
  facts: z.array(z.string()).default([]),
  /** For SoftwareApplication JSON-LD. */
  version: z.string().optional(),
  /** Hero demo: a silent loop, with the full (sound) video on YouTube. */
  video: z
    .object({
      /** Public path of the silent MP4; its poster is `<src minus .mp4>.poster.jpg`. */
      src: z.string().startsWith("/"),
      alt: z.string(),
      youtube: z.object({
        id: z.string(),
        title: z.string(),
        description: z.string(),
        uploadDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
      }),
    })
    .optional(),
  /** "How it works" — numbered steps above the screenshot gallery. */
  steps: z.array(z.string()).default([]),
  /** Screenshots: public path of the PNG; AVIF/WebP siblings are derived. */
  gallery: z
    .array(z.object({ src: z.string().endsWith(".png"), alt: z.string(), caption: z.string() }))
    .default([]),
  sections: z
    .array(
      z.object({
        kicker: z.string(),
        heading: z.string(),
        paragraphs: z.array(z.string()).default([]),
        items: z.array(z.string()).default([]),
      }),
    )
    .default([]),
  /** Rendered verbatim AND emitted as FAQPage JSON-LD — one source, no drift. */
  faq: z.array(faqSchema).default([]),
  /** Descriptive outbound links (replace the generic "tool page" button). */
  links: z.array(z.object({ label: z.string(), href: z.string().url() })).default([]),
  /** Page-specific og:image (public path, 1200×630). */
  ogImage: z.string().startsWith("/").optional(),
});
export type ExtensionPageInput = z.input<typeof extensionPageSchema>;

export interface MediaSize {
  width: number;
  height: number;
}

const mediaFiles = import.meta.glob("../content/extension-media.json", {
  eager: true,
  import: "default",
});
const MEDIA = (Object.values(mediaFiles)[0] ?? {}) as Record<string, MediaSize>;

export const posterPath = (videoSrc: string) => videoSrc.replace(/\.mp4$/, ".poster.jpg");
export const youtubeWatchUrl = (id: string) => `https://www.youtube.com/watch?v=${id}`;

function sized(path: string, slug: string): MediaSize | null {
  const size = MEDIA[path];
  if (!size)
    console.warn(`[extension-pages] "${slug}": ${path} not in extension-media.json — hidden`);
  return size ?? null;
}

function resolve(raw: z.infer<typeof extensionPageSchema>) {
  const { video, gallery, ogImage, slug } = raw;
  const videoSize = video ? sized(video.src, slug) : null;
  const ogSize = ogImage ? sized(ogImage, slug) : null;
  const posterSize = video ? sized(posterPath(video.src), slug) : null;
  return {
    ...raw,
    // The YouTube video stands on its own; only the local hero loop needs files.
    heroVideo: video && videoSize && posterSize ? { ...video, size: posterSize } : null,
    gallery: gallery.flatMap((g) => {
      const size = sized(g.src, slug);
      return size ? [{ ...g, size }] : [];
    }),
    og: ogImage && ogSize ? { src: ogImage, size: ogSize } : null,
  };
}
export type ExtensionPage = ReturnType<typeof resolve>;

const files = import.meta.glob("../content/extension-pages/*.ts", {
  eager: true,
  import: "default",
});

const PAGES = new Map<string, ExtensionPage>();
for (const [path, raw] of Object.entries(files)) {
  const parsed = extensionPageSchema.safeParse(raw);
  if (!parsed.success) {
    console.error(`[extension-pages] invalid ${path}:`, parsed.error.flatten());
    continue;
  }
  PAGES.set(parsed.data.slug, resolve(parsed.data));
}

export function getExtensionPage(slug: string): ExtensionPage | undefined {
  return PAGES.get(slug);
}

const PUBLISHER = { "@type": "Organization", name: "LaMill", url: `${SITE_ORIGIN}/` };

/**
 * One @graph: SoftwareApplication, FAQPage (from the same `faq[]` the page
 * renders), BreadcrumbList, and VideoObject when there's a YouTube demo.
 * No ratings/reviews — none exist.
 */
export function extensionJsonLd(ext: Extension, page: ExtensionPage | undefined) {
  const url = canonicalUrl(`/extensions/${ext.slug}`);
  const graph: Record<string, unknown>[] = [
    {
      "@type": "SoftwareApplication",
      name: ext.name,
      description: page?.description ?? ext.pitch,
      url,
      applicationCategory: "BrowserApplication",
      operatingSystem: "Chrome",
      ...(page?.version ? { softwareVersion: page.version } : {}),
      ...(ext.store_url ? { installUrl: ext.store_url, downloadUrl: ext.store_url } : {}),
      ...(page?.og ? { image: `${SITE_ORIGIN}${page.og.src}` } : {}),
      offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
      publisher: PUBLISHER,
    },
    {
      "@type": "BreadcrumbList",
      itemListElement: [
        { "@type": "ListItem", position: 1, name: "Home", item: canonicalUrl("/") },
        { "@type": "ListItem", position: 2, name: "Extensions", item: canonicalUrl("/extensions") },
        { "@type": "ListItem", position: 3, name: ext.name, item: url },
      ],
    },
  ];
  if (page?.faq.length) {
    graph.push({
      "@type": "FAQPage",
      mainEntity: page.faq.map((f) => ({
        "@type": "Question",
        name: f.q,
        acceptedAnswer: { "@type": "Answer", text: f.a },
      })),
    });
  }
  const yt = page?.video?.youtube;
  if (yt) {
    graph.push({
      "@type": "VideoObject",
      name: yt.title,
      description: yt.description,
      uploadDate: yt.uploadDate,
      thumbnailUrl: `https://i.ytimg.com/vi/${yt.id}/hqdefault.jpg`,
      embedUrl: `https://www.youtube.com/embed/${yt.id}`,
      url: youtubeWatchUrl(yt.id),
      publisher: PUBLISHER,
    });
  }
  return { "@context": "https://schema.org", "@graph": graph };
}
